CREATE TABLE public.staff_private_access(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_id uuid NOT NULL,entity_id text NOT NULL,city_id uuid,created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.staff_private_access TO authenticated; GRANT ALL ON public.staff_private_access TO service_role; ALTER TABLE public.staff_private_access ENABLE ROW LEVEL SECURITY; CREATE POLICY "Owner privacy review" ON public.staff_private_access FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM app_owner WHERE user_id=auth.uid())); CREATE INDEX staff_private_access_actor_time ON public.staff_private_access(actor_id,created_at);
CREATE OR REPLACE FUNCTION public.staff_authorize_private_document(_path text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE city uuid; ref text; amount integer; caseid uuid; BEGIN
 IF NOT staff_enabled(auth.uid()) OR NOT (has_role(auth.uid(),'admin') OR staff_partner_document_allowed(_path)) THEN RAISE EXCEPTION 'Private document access denied'; END IF;
 SELECT a.city_id,a.id::text INTO city,ref FROM partner_applications a WHERE _path IN (a.cnic_image_url,a.shop_image_url,a.extra->>'cnic_back_url',a.extra->>'selfie_url',a.extra->>'cheque_path') LIMIT 1;
 IF ref IS NULL THEN SELECT a.city_id,a.id::text INTO city,ref FROM rider_verifications v JOIN partner_applications a ON a.id=v.application_id WHERE _path IN (v.front_url,v.back_url,v.selfie_url) LIMIT 1; END IF;
 IF ref IS NULL THEN SELECT r.city_id,m.id::text INTO city,ref FROM rider_remittances m JOIN riders r ON r.id=m.rider_id WHERE m.receipt_url=_path LIMIT 1; END IF;
 IF ref IS NULL THEN RAISE EXCEPTION 'Document must belong to a recorded case'; END IF;
 INSERT INTO staff_private_access(actor_id,entity_id,city_id) VALUES(auth.uid(),ref,city);
 SELECT count(*) INTO amount FROM staff_private_access WHERE actor_id=auth.uid() AND created_at>now()-interval '1 hour';
 IF amount>=50 THEN INSERT INTO staff_cases(source_kind,source_id,city_id,department,title,next_action) VALUES('privacy_review',auth.uid()::text||':'||to_char(now() AT TIME ZONE 'Asia/Karachi','YYYY-MM-DD-HH24'),city,'partners','نجی ثبوت کی کثرت؛ آزاد جائزہ','کام کے بوجھ اور جائز ضرورت کی تصدیق؛ خودکار الزام نہیں') ON CONFLICT(source_kind,source_id) DO NOTHING RETURNING id INTO caseid; IF caseid IS NOT NULL THEN PERFORM notify_user((SELECT user_id FROM app_owner LIMIT 1),'privacy_review','نجی رسائی کا جائزہ','نجی ثبوت زیادہ کھولے گئے؛ آزاد جانچ درکار ہے','/admin'); END IF; END IF;
 INSERT INTO staff_audit_log(actor_id,action,entity_type,entity_id,city_id,details) VALUES(auth.uid(),'private_read','partner_applications',ref,city,jsonb_build_object('private_access',true)); RETURN true; END $$;
ALTER POLICY "Users read own partner docs" ON storage.objects USING(bucket_id='partner-documents' AND split_part(name,'/',1)=auth.uid()::text);
ALTER POLICY "service evidence participant read" ON storage.objects USING(bucket_id='service-evidence' AND EXISTS(SELECT 1 FROM service_bookings b WHERE b.id::text=(storage.foldername(name))[2] AND (b.customer_id=auth.uid() OR mechanic_can_access_booking(auth.uid(),b.id) OR can_supervise_service(b.id))));
ALTER POLICY "Riders view own delivery proofs" ON storage.objects USING(bucket_id='delivery-proofs' AND ((storage.foldername(name))[1]=auth.uid()::text OR has_role(auth.uid(),'admin') OR CASE WHEN (storage.foldername(name))[1] ~* '^[0-9a-f-]{36}$' THEN staff_rider_allowed('support',(storage.foldername(name))[1]::uuid) ELSE false END));
REVOKE ALL ON FUNCTION public.staff_authorize_private_document(text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.staff_authorize_private_document(text) TO authenticated,service_role;